const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2007-08-10';
  const endDate = '2007-08-21'; // GEE end date is exclusive

  // Define representative regions
  const centralOklahoma = ee.Geometry.Rectangle([-98.0, 35.0, -97.0, 36.0]); // Bounding box for central Oklahoma
  const northernTexas = ee.Geometry.Rectangle([-97.0, 32.0, -96.0, 33.0]);   // Bounding box for northern Texas

  // 2. Data Acquisition
  let chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .select('precipitation');

  // Check if collection is empty
  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log("No CHIRPS data found for the specified date range.");
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found: ${collectionSize}`);

  // Calculate total precipitation over the period
  const totalPrecipitation = chirps.sum();

  // 3. Processing & Calculation
  // Define reduction scale (CHIRPS resolution is ~5.5km, use a suitable scale)
  const scale = 5000; // meters

  // Function to get mean precipitation for a region
  const getMeanPrecipitation = async (geometry, regionName) => {
    const stats = await totalPrecipitation.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    // Check for C3: Calculation Failure (None, NaN)
    if (stats === null || isNaN(stats)) {
      console.log(`Calculation failed for ${regionName}.`);
      console.log("C3");
      return null;
    }

    // Check for C2: No Valid Pixels (e.g., if stats is 0 but it's not a valid 0)
    // For CHIRPS, a 0 is a valid measurement of no rain. So C2 is less likely unless region is truly empty.
    // However, if the underlying reducer returns 0 due to no overlapping pixels with the geometry, it could be C2.
    // To properly check C2, one would typically use ee.Reducer.count() and check if it's 0.
    // For precipitation, 0 is a valid value, so we'll proceed unless it's null/NaN.
    return stats;
  };

  const okPrecip = await getMeanPrecipitation(centralOklahoma, 'Central Oklahoma');
  const txPrecip = await getMeanPrecipitation(northernTexas, 'Northern Texas');

  if (okPrecip === null || txPrecip === null) {
    // C3 was already printed in getMeanPrecipitation if applicable
    return;
  }

  console.log(`Central Oklahoma Avg Total Precip (${startDate} to ${endDate}): ${okPrecip.toFixed(2)} mm`);
  console.log(`Northern Texas Avg Total Precip (${startDate} to ${endDate}): ${txPrecip.toFixed(2)} mm`);

  // 4. Validation & Final Answer
  if (okPrecip > txPrecip) {
    console.log("A"); // Yes, Central Oklahoma experienced more rainfall
  } else {
    console.log("B"); // No, Central Oklahoma did not experience more rainfall (it was less or equal)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
